ACKS = "t_xxxxxxxx-xxxxx"; // fallbacks\n\nconst modo = Number($getTag(MODO));\nconst seq = $getTag(SEQ);\nconst agora = Date.now();\nconst wd =\n  globalThis.wd ||\n  (globalThis.wd = { seq: seq, desde: agora, modo: modo, disparou: false });\n// recome\xe7a a contar quando chega seq novo OU quando o operador acabou de escolher o modo 0\nif (seq !== wd.seq || (modo === 0 && wd.modo !== 0)) {\n  wd.seq = seq;\n  wd.desde = agora;\n  wd.disparou = false;\n}\nwd.modo = modo;\nconst idade = Math.round((agora - wd.desde) / 1000);\n$setTag(IDADE, idade);\nif (modo === 0 && idade > LIMITE_S && !wd.disparou) {\n  wd.disparou = true; // uma vez s\xf3 (a leitura do modo demora um ciclo)\n  $setTag(MODO_MB, 2); // fallback: PI interno\n  $setTag(OK, 0);\n  $setTag(FALLBACKS, Number($getTag(FALLBACKS) || 0) + 1);\n  console.log(\n    "supervisor: PI externo sem resposta ha " + idade + " s -> modo 2",\n  );\n} else if (modo === 0 && idade <= LIMITE_S) {\n  $setTag(OK, 1); // em modo 0 e o Node-RED respondendo\n}\n'})}),"\n",(0,r.jsxs)(s.p,{children:["Troque os tr\xeas ",(0,r.jsx)(s.code,{children:"t_xxxxxxxx-xxxxx"})," pelos ids das suas tags do FUXA Server: no editor de\nscripts, o seletor de tags insere o id. Os nomes ",(0,r.jsx)(s.strong,{children:"das conex\xf5es e das tags"})," usados no\n",(0,r.jsx)(s.code,{children:"$getTagId"})," t\xeam de ser ",(0,r.jsx)(s.strong,{children:"exatamente"})," os da T2."]}),"\n"]}),"\n",(0,r.jsxs)(s.li,{children:["\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"FUXA: alarme e tela"})}),"\n",(0,r.jsxs)(s.ul,{children:["\n",(0,r.jsxs)(s.li,{children:["Alarme ",(0,r.jsx)(s.code,{children:"Controlador externo"}),", tag ",(0,r.jsx)(s.code,{children:"pi_externo_ok"}),", ",(0,r.jsx)(s.strong,{children:"High High"})," na faixa ",(0,r.jsx)(s.strong,{children:"0\u20130"}),',\ntexto "PI do Node-RED parado: supervisor voltou ao PI interno", grupo ',(0,r.jsx)(s.code,{children:"Supervisao"}),",\n",(0,r.jsx)(s.em,{children:"Ack by active Alarm a